{
  "root_causes": [
    {
      "service": "product-catalog",
      "fault_kind": "application_method_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'abn' AS p, count(*) AS n, sum(CASE WHEN duration>60e9 THEN 1 ELSE 0 END) AS over_60s, round(quantile_cont(duration,0.5)/1e6,1) AS p50_ms FROM abnormal_traces WHERE service_name='product-catalog' AND span_name LIKE '%GetProduct%' UNION ALL SELECT 'norm', count(*), sum(CASE WHEN duration>60e9 THEN 1 ELSE 0 END), round(quantile_cont(duration,0.5)/1e6,1) FROM normal_traces WHERE service_name='product-catalog' AND span_name LIKE '%GetProduct%'",
          "claim": "Abnormal GetProduct server spans exceed 60s in 22 of 164 (normal 13 of 176); median stays about 1 ms."
        },
        {
          "kind": "trace",
          "sql": "SELECT round(s.duration/1e6,0) AS slow_ms, round(c.duration/1e6,2) AS child_sql_ms, c.span_name FROM abnormal_traces s JOIN abnormal_traces c ON c.trace_id=s.trace_id AND c.parent_span_id=s.span_id WHERE s.service_name='product-catalog' AND s.span_name LIKE '%GetProduct%' AND s.duration>1e9 ORDER BY 1 LIMIT 20",
          "claim": "The 130-second GetProduct spans spend that time in-process before a sql.conn.query child that itself takes under 1 ms."
        },
        {
          "kind": "trace",
          "sql": "SELECT 'abn' AS p, count(*) AS n, sum(CASE WHEN duration>1e9 THEN 1 ELSE 0 END) AS slow_gt1s FROM abnormal_traces WHERE service_name='frontend' AND span_name='GET /api/products/[productId]/index' UNION ALL SELECT 'norm', count(*), sum(CASE WHEN duration>1e9 THEN 1 ELSE 0 END) FROM normal_traces WHERE service_name='frontend' AND span_name='GET /api/products/[productId]/index'",
          "claim": "User product-page requests over 1 s rose to 15 of 81 from 4 of 80 in normal."
        }
      ]
    },
    {
      "service": "checkout",
      "fault_kind": "http_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'abn_checkout_client' AS src, count(*) AS n, round(quantile_cont(duration,0.5)/1e6,1) AS p50_ms, round(quantile_cont(duration,0.95)/1e6,1) AS p95_ms FROM abnormal_traces WHERE service_name='checkout' AND span_name LIKE '%PaymentService/Charge%' UNION ALL SELECT 'abn_payment_server', count(*), round(quantile_cont(duration,0.5)/1e6,1), round(quantile_cont(duration,0.95)/1e6,1) FROM abnormal_traces WHERE service_name='payment' AND span_name LIKE '%PaymentService/Charge%' UNION ALL SELECT 'norm_checkout_client', count(*), round(quantile_cont(duration,0.5)/1e6,1), round(quantile_cont(duration,0.95)/1e6,1) FROM normal_traces WHERE service_name='checkout' AND span_name LIKE '%PaymentService/Charge%'",
          "claim": "Checkout's Charge calls to payment take about 442 ms (normal 2.6 ms) while payment's server Charge spans stay about 1.2 ms."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, count(*) AS n, round(quantile_cont(duration,0.5)/1e6,1) AS p50_ms FROM abnormal_traces WHERE service_name='checkout' AND attr_span_kind='Client' GROUP BY 1,2 ORDER BY 2",
          "claim": "Only the Charge path is shifted by a fixed delay; checkout's other outgoing calls (cart, currency, shipping) keep their normal medians."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "product-catalog",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, count(*) AS n, sum(CASE WHEN duration>1e9 THEN 1 ELSE 0 END) AS slow_gt1s, round(quantile_cont(duration,0.95)/1e6,0) AS p95_ms FROM abnormal_traces WHERE service_name='frontend' AND span_name='grpc.oteldemo.ProductCatalogService/GetProduct' GROUP BY 1,2",
          "claim": "Frontend's GetProduct calls to product-catalog show a p95 near 130 s, with 21 of 153 calls over 1 s."
        }
      ]
    },
    {
      "from": "product-catalog",
      "to": "checkout",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_span_kind AS k, count(*) AS n, round(quantile_cont(duration,0.5)/1e6,1) AS p50_ms, round(quantile_cont(duration,0.95)/1e6,1) AS p95_ms FROM abnormal_traces WHERE service_name='checkout' AND span_name LIKE '%ProductCatalog%' GROUP BY 1,2",
          "claim": "Checkout's GetProduct calls to product-catalog reach p95 of about 64.8 s, against 6.5 s in normal."
        }
      ]
    },
    {
      "from": "checkout",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "WITH tr AS (SELECT DISTINCT trace_id FROM abnormal_traces WHERE service_name='checkout') SELECT t.service_name, t.span_name, count(*) AS n, round(quantile_cont(t.duration,0.5)/1e6,0) AS p50_ms FROM abnormal_traces t WHERE t.trace_id IN (SELECT trace_id FROM tr) AND t.service_name='frontend' AND t.attr_span_kind='Server' GROUP BY 1,2",
          "claim": "Frontend POST requests whose traces include checkout spans all run about 15 s, the client timeout."
        }
      ]
    },
    {
      "from": "frontend",
      "to": "frontend-proxy",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, count(*) AS n, sum(CASE WHEN duration>1e9 THEN 1 ELSE 0 END) AS slow_gt1s, round(quantile_cont(duration,0.95)/1e6,0) AS p95_ms FROM abnormal_traces WHERE service_name='frontend-proxy' AND span_name='ingress' AND attr_span_kind='Server' GROUP BY 1,2",
          "claim": "Frontend-proxy ingress requests show 48 of 218 over 1 s, carrying the slow frontend calls to users."
        }
      ]
    }
  ]
}
